// Extract text content from HTML
const html = $input.first().json.body;

// Simple HTML to text extraction
let text = html
  .replace(/<script[^>]*>[\s\S]*?<\/script>/gi, '')
  .replace(/<style[^>]*>[\s\S]*?<\/style>/gi, '')
  .replace(/<[^>]+>/g, ' ')
  .replace(/\s+/g, ' ')
  .trim();

// Limit to first 8000 chars for AI processing
text = text.substring(0, 8000);

// Get the original input data
const inputData = $('Webhook Trigger').first().json.body;

return {
  website_text: text,
  client_url: inputData.client_url,
  client_name: inputData.client_name || 'Unknown',
  project_id: inputData.project_id || null,
  competitors_hint: inputData.competitors || ''
};

