parameters.jsCode:
// Parse AI response and structure output
const aiResponse = $input.first().json.message.content;

let brandProfile;
try {
  // Try to parse the JSON from AI response
  const jsonMatch = aiResponse.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    brandProfile = JSON.parse(jsonMatch[0]);
  } else {
    throw new Error('No JSON found in response');
  }
} catch (e) {
  brandProfile = {
    error: 'Failed to parse AI response',
    raw_response: aiResponse
  };
}

// Get original input data
const inputData = $('Extract Text from HTML').first().json;

return {
  project_id: inputData.project_id,
  client_url: inputData.client_url,
  client_name: inputData.client_name,
  brand_profile: brandProfile,
  generated_at: new Date().toISOString(),
  status: 'completed'
};

